### 项目地址

https://github.com/free-revalution/HuiNet-Network-Core

### 类别

人工智能

### 项目标题

HuiNet 是一个革命性的去中心化 P2P 网络库，专为 Agent-to-Agent (A2A) 通信设计，让 AI 智能体能够无缝协作与交流！

### 项目描述

HuiNet 是一个去中心化的 P2P 网络库，让 AI Agents（如 Claude Code、OpenAI Codex 等）能够在不同计算机和网络之间直接通信。通过自动发现和加密消息传递，实现跨网络的 Agent 协作。

项目使用 TypeScript + Node.js 构建，采用 Ed25519 公钥加密保障通信安全，支持 mDNS 本地网络自动发现。

⚠️ 声明： 这是一个学习型项目，旨在探索分布式系统和 P2P 网络技术。目前处于早期开发阶段，欢迎贡献者和反馈！

### 亮点

1. HuiNet 使用 UDP 组播实现零配置的节点发现。当节点启动时，会自动向局域网广播自己的存在
2. 所有 P2P 消息都使用 Ed25519 签名验证，确保消息来源可信
3. HuiNet 实现了紧凑的二进制消息协议，使用 Varint 编码减少消息大小
4. HuiNet 实现了高效的三层路由表，根据连接频率自动调整节点层级

### 示例代码

```markdown
// mDNS 本地网络自动发现
export class MDiscoveryService extends EventEmitter {
  async start(): Promise<void> {
    // 创建支持地址复用的 UDP socket
    this.socket = dgram.createSocket({
      type: 'udp4',
      reuseAddr: true
    });

    // 绑定到组播端口 43000
    this.socket.bind(this.multicastPort, this.bindAddress, () => {
      // 加入组播组 224.0.0.114
      this.socket!.addMembership(this.multicastAddress);
      this.socket!.setBroadcast(true);
      this.socket!.setMulticastTTL(1);
    });
  }

  // 向网络广播自己的存在
  announce(): void {
    const message: DiscoveryMessage = {
      type: 'announce',
      nodeId: this.nodeId,
      port: this.port,
      timestamp: Date.now()
    };

    // 发送到组播地址
    this.socket.send(
      Buffer.from(JSON.stringify(message)),
      this.multicastPort,
      this.multicastAddress
    );
  }
}

// Ed25519 端到端加密
import * as nacl from 'tweetnacl';

export function signMessage(message: Buffer, privateKey: Buffer): Buffer {
  if (privateKey.length !== 64) {
    throw new Error(`Invalid private key length: ${privateKey.length}. Expected 64 bytes for Ed25519`);
  }

  // 使用 tweetnacl 进行 Ed25519 签名
  const signature = nacl.sign.detached(
    new Uint8Array(message),
    new Uint8Array(privateKey)
  );

  return Buffer.from(signature);
}

export function verifySignature(
  message: Buffer,
  signature: Buffer,
  publicKey: Buffer
): boolean {
  if (signature.length !== 64) {
    throw new Error(`Invalid signature length: ${signature.length}. Expected 64 bytes`);
  }
  if (publicKey.length !== 32) {
    throw new Error(`Invalid public key length: ${publicKey.length}. Expected 32 bytes`);
  }

  // 验证签名
  return nacl.sign.detached.verify(
    new Uint8Array(message),
    new Uint8Array(signature),
    new Uint8Array(publicKey)
  );
}

// 二进制消息协议 (Varint 编码)
// 消息格式: [header_len:varint][header_json][body_len:varint][body][signature_len:varint][signature]

export function encodeMessage(message: BaseMessage): Buffer {
  const headerJson = JSON.stringify(message.header);
  const headerBuffer = Buffer.from(headerJson, 'utf-8');
  const body = message.body || Buffer.alloc(0);
  const signature = message.signature;

  // 使用 varint 编码长度 (节省空间)
  const headerLen = encodeVarint(headerBuffer.length);
  const bodyLen = encodeVarint(body.length);
  const sigLen = encodeVarint(signature.length);

  return Buffer.concat([headerLen, headerBuffer, bodyLen, body, sigLen, signature]);
}

// Varint 编码: 小于 128 的数字只占 1 字节
function encodeVarint(value: number): Buffer {
  const buffer = Buffer.allocUnsafe(5);
  let offset = 0;

  do {
    let byte = value & 0x7F;  // 取低 7 位
    value >>>= 7;              // 右移 7 位
    if (value !== 0) byte |= 0x80;  // 设置继续位
    buffer[offset++] = byte;
  } while (value !== 0);

  return buffer.subarray(0, offset);
}
